--
-- Table structure for table `ocr_scan`
--

DROP TABLE IF EXISTS `ocr_scan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ocr_scan` (
  `scan_id` int NOT NULL AUTO_INCREMENT,
  `session_id` int DEFAULT NULL,
  `gate_id` int DEFAULT NULL,
  `image_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `detected_plate` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plate_confidence_score` float DEFAULT NULL,
  `corrected_plate` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_corrected` tinyint(1) NOT NULL DEFAULT '0',
  `corrected_by_user_id` int DEFAULT NULL,
  `corrected_at` datetime DEFAULT NULL,
  `correction_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trigger_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `process_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scanned_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`scan_id`),
  KEY `session_id` (`session_id`),
  KEY `gate_id` (`gate_id`),
  KEY `corrected_by_user_id` (`corrected_by_user_id`),
  CONSTRAINT `ocr_scan_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `parking_session` (`session_id`),
  CONSTRAINT `ocr_scan_ibfk_2` FOREIGN KEY (`gate_id`) REFERENCES `gate` (`gate_id`),
  CONSTRAINT `ocr_scan_ibfk_3` FOREIGN KEY (`corrected_by_user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

