DROP TABLE IF EXISTS `parking_session`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `parking_session` (
  `session_id` int NOT NULL AUTO_INCREMENT,
  `booking_id` int DEFAULT NULL,
  `slot_id` int NOT NULL,
  `user_id` int NOT NULL,
  `vehicle_id` int NOT NULL,
  `entry_gate_id` int DEFAULT NULL,
  `exit_gate_id` int DEFAULT NULL,
  `entry_time` datetime DEFAULT NULL,
  `exit_time` datetime DEFAULT NULL,
  `entry_mode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`session_id`),
  KEY `booking_id` (`booking_id`),
  KEY `slot_id` (`slot_id`),
  KEY `user_id` (`user_id`),
  KEY `vehicle_id` (`vehicle_id`),
  KEY `entry_gate_id` (`entry_gate_id`),
  KEY `exit_gate_id` (`exit_gate_id`),
  CONSTRAINT `parking_session_ibfk_1` FOREIGN KEY (`booking_id`) REFERENCES `booking` (`booking_id`),
  CONSTRAINT `parking_session_ibfk_2` FOREIGN KEY (`slot_id`) REFERENCES `parking_slot` (`slot_id`),
  CONSTRAINT `parking_session_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`),
  CONSTRAINT `parking_session_ibfk_4` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicle` (`vehicle_id`),
  CONSTRAINT `parking_session_ibfk_5` FOREIGN KEY (`entry_gate_id`) REFERENCES `gate` (`gate_id`),
  CONSTRAINT `parking_session_ibfk_6` FOREIGN KEY (`exit_gate_id`) REFERENCES `gate` (`gate_id`)
) ENGINE=InnoDB AUTO_INCREMENT=532 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
