CREATE TABLE `parking_slot` (
  `slot_id` int NOT NULL AUTO_INCREMENT,
  `zone_id` int NOT NULL,
  `slot_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slot_size` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` int DEFAULT NULL,
  `distance_to_gate` int DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`slot_id`),
  UNIQUE KEY `uk_slot_zone_code` (`zone_id`,`slot_code`),
  CONSTRAINT `parking_slot_ibfk_1` FOREIGN KEY (`zone_id`) REFERENCES `zone` (`zone_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1190 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
